ServerEvents.recipes(event => {
    let n = 0;
    Object.keys(TACZ_RECIPES).forEach(function(rid) {
        try {
            event.remove({ id: rid });
            event.custom(TACZ_RECIPES[rid]).id(rid);
            n++;
        } catch (e) {
            console.warn("[TaCZ Balance] " + rid + " failed: " + e);
        }
    });
    console.info("[TaCZ Balance] Injected " + n + " gun recipes with cores.");
});
